785	impl<'t, Lex: LexerWithCheckpoint<'t>> Iterator for LookaheadIterator<'_, 't, Lex> {
786	    type Item = LookaheadToken<Lex::Kind>;
787	
788	    #[inline]
789	    fn next(&mut self) -> Option<Self::Item> {
790	        let lookbehind = &self.buffered.lookahead;
791	        self.nth += 1;
792	
793	        // Is the `nth` token already in the cache, then return it
794	        if let Some(lookbehind) = lookbehind.get_checkpoint(self.nth - 1) {
795	            let lookahead = LookaheadToken::from(lookbehind);
796	            return Some(lookahead);
797	        }
798	
799	        let lexer = &mut self.buffered.inner;
800	
801	        // We're already at the end, calling next now only returns `EOF` again. End the iterator.
802	        if lexer.current() == SyntaxKind::EOF {
803	            return None;
804	        }
805	
806	        // Store the current token before moving the inner lexer forward if we haven't done so.
807	        // Necessary to prevent that [BufferedLexer::current] moves forward when performing lookahead.
808	        if self.buffered.current.is_none() {
809	            self.buffered.current = Some(lexer.checkpoint());
810	        }
811	
812	        let kind = lexer.next_token(Lex::LexContext::default());
813	        // Lex the next token and cache it in the lookahead cache. Needed to cache it right away
814	        // because of the diagnostic.
815	        self.buffered.lookahead.push_back(lexer.checkpoint());
816	
817	        Some(LookaheadToken {
818	            kind,
819	            flags: lexer.current_flags(),
820	        })
821	    }
822	}
