190	fn parse_any_tag_name(p: &mut HtmlParser) -> ParsedSyntax {
191	    if !is_at_start_literal(p) {
192	        return Absent;
193	    }
194	    let tag_text = p.cur_text();
195	
196	    // Check if this could be a component or has member expression
197	    let is_component = is_possible_component(p, tag_text);
198	    let has_member_expression = !p.options().is_html() && p.nth_at(1, T![.]);
199	
200	    // Step 1: Parse base name
201	    let name = if is_component || has_member_expression {
202	        // Parse as component name - use component_name_context to allow `.` for member expressions
203	        let m = p.start();
204	        p.bump_with_context(HTML_LITERAL, component_name_context(p));
205	        Present(m.complete(p, HTML_COMPONENT_NAME))
206	    } else {
207	        // Parse as regular HTML tag
208	        parse_literal(p, HTML_TAG_NAME)
209	    };
210	    // Step 2: Extend with member access if present (using .map() pattern from JSX parser)
211	    name.map(|mut name| {
212	        // Check kind BEFORE moving name with precede()
213	        let is_lowercase_tag = name.kind(p) == HTML_TAG_NAME;
214	
215	        while p.at(T![.]) {
216	            // Convert BEFORE precede takes ownership of name
217	            if is_lowercase_tag {
218	                name.change_kind(p, HTML_COMPONENT_NAME);
219	            }
220	            let m = name.precede(p);
221	            p.bump_with_context(T![.], component_name_context(p));
222	            if is_at_start_literal(p) {
223	                let member_m = p.start();
224	                p.bump_with_context(HTML_LITERAL, component_name_context(p));
225	                member_m.complete(p, HTML_TAG_NAME);
226	            } else {
227	                p.error(expected_element_name(p, p.cur_range()));
228	            }
229	
230	            name = m.complete(p, HTML_MEMBER_NAME);
231	        }
232	        name
233	    })
234	}
