/// Returns `true` if the parser is at a closing tag (`</...>`) whose tag name is
/// a void element (e.g. `</br>`, `</input>`).
///
/// Void elements should not have a closing tag, so such closing tags are parsed
/// as bogus elements instead of being treated as the closing tag for an
/// enclosing element. This peeks at the tag name without consuming any tokens.
fn is_at_void_element_closing_tag(p: &mut HtmlParser) -> bool {
    if !p.at(T![<]) || !p.nth_at(1, T![/]) {
        return false;
    }

    let checkpoint = p.checkpoint();
    p.bump_with_context(T![<], inside_tag_context(p));
    p.bump_with_context(T![/], inside_tag_context(p));
    let is_void_element = VOID_ELEMENTS
        .iter()
        .any(|tag| tag.eq_ignore_ascii_case(p.cur_text()))
        && !is_possible_component(p, p.cur_text());
    p.rewind(checkpoint);
    is_void_element
}

